+import 'dart:convert';
+
+class ReleaseNote {
+  const ReleaseNote({
+    required this.id,
+    required this.title,
+    required this.summary,
+    required this.platforms,
+    required this.kind,
+    this.required = false,
+  });
+
+  final String id;
+  final String title;
+  final String summary;
+  final Set<String> platforms;
+  final String kind;
+  final bool required;
+
+  bool includesChannel(String channel) =>
+      platforms.contains(channel) ||
+      (platforms.contains('ios') &&
+          const {'ios-app-store', 'ios-testflight'}.contains(channel));
+
+  static ReleaseNote? parse(Object? value, {bool required = false}) {
+    if (value is! Map) return null;
+    final id = value['id'];
+    final title = value['title'];
+    final summary = value['summary'];
+    final platforms = value['platforms'];
+    final kind = value['kind'];
+    if (id is! String ||
+        !RegExp(r'^[a-z0-9][a-z0-9-]{0,79}$').hasMatch(id) ||
+        title is! String ||
+        title.trim().isEmpty ||
+        title.length > 160 ||
+        summary is! String ||
+        summary.trim().isEmpty ||
+        summary.length > 1000 ||
+        platforms is! List ||
+        platforms.isEmpty ||
+        platforms.any(
