+        isDisliked: helpful ? review.viewer.isDisliked : on,
+      ),
+      helpfulCount: helpful
+          ? (nextCount < 0 ? 0 : nextCount)
+          : review.helpfulCount,
+      dislikeCount: helpful
+          ? review.dislikeCount
+          : (nextCount < 0 ? 0 : nextCount),
+    );
+  }
