diff --git a/apps/mobile/packages/forum_app/test/release_notes_test.dart b/apps/mobile/packages/forum_app/test/release_notes_test.dart
new file mode 100644
index 00000000..05449d76
--- /dev/null
+++ b/apps/mobile/packages/forum_app/test/release_notes_test.dart
@@ -0,0 +1,595 @@
+import 'dart:convert';
+import 'dart:io';
+import 'dart:typed_data';
+
+import 'package:dio/dio.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:forum_app/src/updates/android_release.dart';
+import 'package:forum_app/src/updates/release_notes.dart';
+import 'package:forum_app/src/updates/ios_store_release.dart';
+import 'package:shared_preferences/shared_preferences.dart';
+
+Map<String, dynamic> note(
+  String id,
+  String title, {
+  List<String> platforms = const ['android'],
+  bool required = false,
+  String kind = 'feature',
+}) => {
+  'id': id,
+  'title': title,
+  'summary': '$title summary',
+  'platforms': platforms,
+  'kind': kind,
+  if (required) 'required': true,
+};
+
+Map<String, dynamic> release(
+  int build, {
+  List<String> channels = const ['android'],
+  List<dynamic> highlights = const [],
+  List<dynamic> breaking = const [],
+  List<dynamic> actions = const [],
+}) => {
+  'version': '1.0.${build - 1}',
+  'buildNumber': build,
+  'channels': channels,
+  'highlights': highlights,
+  'breaking': breaking,
+  'requiredActions': actions,
+  'testflightNotes': const [],
+};
+
+Map<String, dynamic> catalog() => {
+  'schemaVersion': 1,
+  'historyCoverage': {
+    'source': 'github-release-receipts',
+    'publishedAt': '2026-10-03T00:00:00Z',
+    'byChannel': {
+      'android': {
+        'completeFromBuild': 4,
+        'throughBuild': 7,
+        'coveredBuilds': [4, 5, 6, 7],
+      },
+      'ios-app-store': {
+        'completeFromBuild': 5,
+        'throughBuild': 6,
+        'coveredBuilds': [6],
+      },
+      'ios-testflight': {
+        'completeFromBuild': 6,
+        'throughBuild': 7,
+        'coveredBuilds': [7],
+      },
+    },
+  },
+  'releases': [
+    release(4),
+    release(
+      5,
+      breaking: [note('shared-update', 'Older title', required: true)],
+    ),
+    release(
+      6,
+      channels: const ['android', 'ios-app-store'],
+      highlights: [
+        note('shared-update', 'Current title'),
+        note('ios-only', 'iOS', platforms: ['ios-app-store']),
+      ],
+    ),
+    {
+      ...release(
+        7,
+        channels: const ['android', 'ios-testflight'],
+        breaking: [
+          note(
+            'important-change',
+            'Important',
+            required: true,
+            kind: 'security',
+          ),
+        ],
+      ),
+      'testflightNotes': [
+        {'id': 'testing-focus', 'text': 'Verify account recovery in the beta.'},
+      ],
+    },
+  ],
+};
+
+void main() {
+  test(
+    'iOS public release lookup is pinned to the Chinese App Store listing',
+    () async {
+      final adapter = _Adapter(
+        (_) => ResponseBody.fromString(
+          jsonEncode({
+            'resultCount': 1,
+            'results': [
+              {
+                'bundleId': appStoreBundleId,
+                'trackId': int.parse(appStoreAppId),
+                'version': '2.3.4',
+                'trackViewUrl':
+                    'https://apps.apple.com/cn/app/yourtj/id$appStoreAppId',
+              },
+            ],
+          }),
+          200,
+          headers: {
+            'content-type': ['application/json'],
+          },
+        ),
+      );
+      final listing = await IosStoreListing.lookup(
+        dio: Dio()..httpClientAdapter = adapter,
+      );
+      expect(listing?.version, '2.3.4');
+      expect(adapter.requests.single.uri.queryParameters['country'], 'cn');
+    },
+  );
+
+  test(
+    'parses the shared publisher fixture and channel-only TestFlight notes',
+    () {
+      final fixture = jsonDecode(
+        File('test/fixtures/mobile_release_catalog.json').readAsStringSync(),
+      );
+      final decoded = ReleaseNoteCatalog.decode(fixture)!;
+      final release43 = decoded.releases.singleWhere(
+        (release) => release.buildNumber == 43,
+      );
+      expect(release43.channels, {'android', 'ios-testflight'});
+      final betaNotes = decoded.forRange(
+        installedBuild: 42,
+        targetBuild: 43,
+        platform: 'ios-testflight',
+      );
+      expect(
+        betaNotes.single.summary,
+        'Verify the course widget after changing a course.',
+      );
+    },
+  );
+
+  test(
+    'TestFlight disclosures stay required and are not repeated as testing notes',
+    () {
+      final decoded = ReleaseNoteCatalog.decode({
+        'schemaVersion': 1,
+        'releases': [
+          {
+            ...release(
+              9,
+              channels: const ['ios-testflight'],
+              actions: [
+                note(
+                  'visit-analytics',
+                  'Visit analytics',
+                  platforms: const ['ios-testflight'],
+                  kind: 'improvement',
+                ),
+              ],
+            ),
+            'testflightNotes': [
+              for (var i = 0; i < 6; i++)
+                {'id': 'check-$i', 'text': 'Check flow $i.'},
+              {
+                'id': 'visit-analytics',
+                'text': 'Visit analytics are on by default.',
+              },
+            ],
+          },
+        ],
+      })!;
+      final notes = decoded.forRange(
+        installedBuild: 8,
+        targetBuild: 9,
+        platform: 'ios-testflight',
+      );
+      expect(notes, hasLength(7));
+      expect(notes.first.id, 'visit-analytics');
+      expect(notes.first.title, 'Visit analytics');
+      expect(notes.first.required, isTrue);
+      expect(
+        promptReleaseNotes(notes).map((entry) => entry.id),
+        contains('visit-analytics'),
+      );
+    },
+  );
+
+  test(
+    'aggregates the exclusive to inclusive build range with channel filtering and required dedup',
+    () {
+      final decoded = ReleaseNoteCatalog.decode(catalog())!;
+      final notes = decoded.forRange(
+        installedBuild: 4,
+        targetBuild: 7,
+        platform: 'android',
+      );
+      expect(notes.map((entry) => entry.id), [
+        'important-change',
+        'shared-update',
+      ]);
+      expect(notes.last.title, 'Current title');
+      expect(notes.last.required, isTrue);
+      expect(notes.last.summary, 'Current title summary');
+      expect(
+        decoded
+            .forRange(
+              installedBuild: 4,
+              targetBuild: 7,
+              platform: 'ios-app-store',
+            )
+            .map((entry) => entry.id),
+        ['ios-only'],
+      );
+      expect(
