+class _Adapter implements HttpClientAdapter {
+  _Adapter(this.reply);
+  final ResponseBody Function(RequestOptions) reply;
+  final requests = <RequestOptions>[];
+
+  @override
+  Future<ResponseBody> fetch(
+    RequestOptions options,
+    Stream<Uint8List>? requestStream,
