+  localizationsDelegates: AppLocalizations.localizationsDelegates,
+  supportedLocales: AppLocalizations.supportedLocales,
+  home: MediaQuery(
+    data: const MediaQueryData(
+      size: Size(320, 640),
+      textScaler: TextScaler.linear(2),
+      disableAnimations: true,
+    ),
+    child: child,
+  ),
+);
+
+bool _insideWindow(WidgetTester tester, Finder finder) {
+  final rect = tester.getRect(finder);
+  return rect.left >= 0 &&
+      rect.top >= 0 &&
+      rect.right <= 320 &&
+      rect.bottom <= 640;
+}
+
+void _expectStatusSemantics(WidgetTester tester, String label) {
+  final finder = find.byKey(const ValueKey('update-status'));
+  expect(finder, findsOneWidget);
+  expect(
+    tester.getSemantics(finder),
+    matchesSemantics(
+      label: label,
+      isLiveRegion: true,
+      children: const <Matcher>[],
+    ),
+  );
+}
+
+class _StatusHarness extends StatefulWidget {
+  const _StatusHarness({super.key});
+
+  @override
+  State<_StatusHarness> createState() => _StatusHarnessState();
+}
+
+class _StatusHarnessState extends State<_StatusHarness> {
+  bool working = false;
+  bool failed = false;
+  bool needsPermission = false;
+  bool ready = false;
+  int receivedBytes = 0;
+
+  void setStatus({
+    bool working = false,
+    bool failed = false,
+    bool needsPermission = false,
+    bool ready = false,
+    int? receivedBytes,
+  }) => setState(() {
+    this.working = working;
+    this.failed = failed;
+    this.needsPermission = needsPermission;
+    this.ready = ready;
+    this.receivedBytes = receivedBytes ?? this.receivedBytes;
+  });
+
+  @override
+  Widget build(BuildContext context) => Center(
+    child: SizedBox(
+      width: 280,
+      child: UpdatePromptSheet(
+        version: '1.2.0',
+        notes: const [],
+        historyComplete: true,
+        working: working,
+        failed: failed,
+        needsPermission: needsPermission,
+        ready: ready,
+        receivedBytes: receivedBytes,
+        primaryLabel: 'Download',
+        onPrimary: () {},
+        onLater: () {},
+      ),
+    ),
+  );
+}
+
+class _DialogHarness extends StatefulWidget {
+  const _DialogHarness({super.key, required this.notes});
+  final List<ReleaseNote> notes;
+
+  @override
+  State<_DialogHarness> createState() => _DialogHarnessState();
+}
+
+class _DialogHarnessState extends State<_DialogHarness> {
+  bool working = false;
+  bool failed = false;
+  bool needsPermission = false;
+  bool ready = false;
+  int receivedBytes = 0;
+  int downloadTapped = 0;
+  int permissionTapped = 0;
+  int cancelTapped = 0;
+
+  void setStatus({
+    bool working = false,
+    bool failed = false,
+    bool needsPermission = false,
+    bool ready = false,
+    int? receivedBytes,
+  }) => setState(() {
+    this.working = working;
+    this.failed = failed;
+    this.needsPermission = needsPermission;
+    this.ready = ready;
+    this.receivedBytes = receivedBytes ?? this.receivedBytes;
+  });
+
+  @override
+  Widget build(BuildContext context) {
+    final l10n = AppLocalizations.of(context);
+    return Scaffold(
+      body: Align(
+        alignment: Alignment.bottomCenter,
+        child: UpdatePromptSheet(
+          version: '1.2.0',
+          installedVersion: '1.1.0',
+          sizeBytes: 5000000,
+          notes: widget.notes,
+          historyComplete: false,
+          working: working,
+          failed: failed,
+          needsPermission: needsPermission,
+          ready: ready,
+          receivedBytes: receivedBytes,
+          primaryLabel: needsPermission
+              ? l10n.updateOpenPermissionSettings
+              : ready
+              ? l10n.updateInstall
+              : failed
+              ? l10n.updateRetry
+              : l10n.updateDownload,
+          onPrimary: () {
+            if (needsPermission) {
+              permissionTapped++;
+            } else {
+              downloadTapped++;
+            }
+          },
+          onCancel: () => cancelTapped++,
+          onLater: () {},
+          onSkip: () {},
+        ),
+      ),
+    );
+  }
+}

