+            onPressed: _uploading ? null : () => Navigator.pop(context),
+            child: Text(l10n.commonCancel),
+          ),
+          FilledButton(
+            onPressed: _uploading ? null : _send,
+            child: Text(_error == null ? l10n.commonSend : l10n.commonRetry),
+          ),
+        ],
+      ),
+    );
+  }
