+
+String _safePngFileName(String value) {
+  final cleaned = value.replaceAll(RegExp(r'[^A-Za-z0-9._-]'), '_');
+  final stem = cleaned.replaceFirst(
+    RegExp(r'\.png$', caseSensitive: false),
+    '',
+  );
+  return '${stem.isEmpty ? 'yourtj-share' : stem}.png';
+}
