diff --git a/apps/mobile/packages/forum_app/test/cache_budget_test.dart b/apps/mobile/packages/forum_app/test/cache_budget_test.dart
new file mode 100644
index 00000000..72e5b8a9
--- /dev/null
+++ b/apps/mobile/packages/forum_app/test/cache_budget_test.dart
@@ -0,0 +1,168 @@
+import 'dart:io';
+
+import 'package:drift/native.dart';
+import 'package:flutter_secure_storage/flutter_secure_storage.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:forum_app/src/offline/drift_cache.dart';
+import 'package:forum_app/src/storage/private_database.dart';
+import 'package:path_provider_platform_interface/path_provider_platform_interface.dart';
+import 'package:sqlite3/sqlite3.dart';
+
+class _Paths extends PathProviderPlatform {
+  _Paths(this.path);
+  final String path;
+  @override
+  Future<String?> getApplicationSupportPath() async => path;
+  @override
+  Future<String?> getApplicationDocumentsPath() async => path;
+}
+
+Future<int> _bytes(File file) async {
+  var total = 0;
+  for (final suffix in ['', '-wal', '-shm']) {
+    final candidate = File('${file.path}$suffix');
+    if (await candidate.exists()) total += await candidate.length();
+  }
+  return total;
+}
+
+Future<int> _pragma(AppDatabase db, String name) async =>
+    (await db.customSelect('PRAGMA $name').getSingle()).read<int>(name);
+
+void main() {
+  TestWidgetsFlutterBinding.ensureInitialized();
+  late Directory directory;
+  late PathProviderPlatform previousPaths;
+  setUp(() async {
+    directory = await Directory.systemTemp.createTemp('cache-budget-');
+    previousPaths = PathProviderPlatform.instance;
+    PathProviderPlatform.instance = _Paths(directory.path);
+    FlutterSecureStorage.setMockInitialValues({});
+  });
+  tearDown(() async {
+    PathProviderPlatform.instance = previousPaths;
+    await directory.delete(recursive: true);
+  });
+
+  test('upgrade reclaims old allocation and enables incremental vacuum', () async {
+    final file = File('${directory.path}/yourtj_cache.sqlite');
+    final raw = sqlite3.open(file.path);
+    raw.execute('PRAGMA user_version = 1');
+    raw.execute(
+      'CREATE TABLE cached_topics(id INTEGER PRIMARY KEY, payload BLOB)',
+    );
+    // The old count-only cache allowed individual payloads over the new limit.
+    raw.execute('INSERT INTO cached_topics VALUES(1, zeroblob(68157440))');
+    raw.execute(
+      'CREATE TABLE campus_snapshots(site TEXT,account_id INTEGER,binding_revision TEXT,schema_version INTEGER,payload TEXT,committed_at TEXT,PRIMARY KEY(site,account_id))',
+    );
+    raw.execute(
+      "INSERT INTO campus_snapshots VALUES('https://fixture.test',7,'binding',1,'keep-campus','now')",
+    );
+    expect(raw.select('PRAGMA auto_vacuum').single.values.single, 0);
+    raw.close();
+    final db = AppDatabase(
+      openPrivateDatabase(
+        name: 'cache',
+        disposable: true,
+        legacyName: 'yourtj_cache',
+      ),
+      physicalBytes: () => privateDatabaseBytes('cache'),
+    );
+    try {
+      expect(await _pragma(db, 'auto_vacuum'), 2);
+      expect(
+        (await db
+                .customSelect('SELECT payload FROM campus_snapshots')
+                .getSingle())
+            .read<String>('payload'),
+        'keep-campus',
+      );
+      expect(await privateDatabaseBytes('cache'), lessThan(2 * 1024 * 1024));
+    } finally {
+      await db.close();
+    }
+  });
+
+  test(
+    'normal batch eviction reclaims free pages without deleting campus',
+    () async {
+      final file = File('${directory.path}/cache.sqlite');
+      final db = AppDatabase(
+        NativeDatabase(
+          file,
+          setup: (raw) {
+            raw.execute('PRAGMA auto_vacuum = INCREMENTAL');
+            raw.execute('PRAGMA journal_mode = WAL');
+          },
+        ),
+        physicalBytes: () => _bytes(file),
+      );
+      try {
+        await db.customStatement(
+          "INSERT INTO campus_snapshots VALUES('https://fixture.test',7,'binding',1,'keep-campus','now')",
+        );
+        await db.customStatement(
+          "INSERT INTO cache_entries VALUES('fixture','chat','old',zeroblob(6291456),0,0,6291456,1)",
+        );
+        expect(await _bytes(file), greaterThan(4 * 1024 * 1024));
+        await DriftOfflineCache(db).putConversations([]);
+        expect(await _bytes(file), lessThan(2 * 1024 * 1024));
+        expect(
+          (await db
+                  .customSelect('SELECT payload FROM campus_snapshots')
+                  .getSingle())
+              .read<String>('payload'),
+          'keep-campus',
+        );
+        expect(await _pragma(db, 'freelist_count'), 0);
+      } finally {
+        await db.close();
+      }
+    },
+  );
+
+  test(
+    'small writes do not vacuum and a physical WAL watermark is reclaimed',
+    () async {
+      final file = File('${directory.path}/cache.sqlite');
+      final db = AppDatabase(
+        NativeDatabase(
+          file,
+          setup: (raw) {
+            raw.execute('PRAGMA auto_vacuum = INCREMENTAL');
+            raw.execute('PRAGMA journal_mode = WAL');
+            raw.execute('PRAGMA wal_autocheckpoint = 0');
+          },
+        ),
+        physicalBytes: () => _bytes(file),
+      );
+      try {
+        await db.customStatement('CREATE TABLE fixture(value BLOB)');
+        await db.customStatement(
+          'INSERT INTO fixture VALUES(zeroblob(1048576))',
+        );
+        await db.customStatement('DELETE FROM fixture');
+        final freePages = await _pragma(db, 'freelist_count');
+        expect(freePages, greaterThan(0));
+        await DriftOfflineCache(db).putConversations([]);
+        expect(await _pragma(db, 'freelist_count'), greaterThan(0));
+        // An uncheckpointed WAL may exceed the target with little live payload.
+        for (var i = 0; i < 33; i++) {
+          await db.customStatement(
+            'INSERT INTO fixture VALUES(zeroblob(2097152))',
+          );
+          await db.customStatement('DELETE FROM fixture');
+        }
+        expect(
+          await _bytes(file),
+          greaterThan(AppDatabase.physicalBudgetBytes),
+        );
+        await db.maintainBudget();
+        expect(await _bytes(file), lessThan(4 * 1024 * 1024));
+      } finally {
+        await db.close();
+      }
+    },
+  );
+}

diff --git a/apps/mobile/packages/forum_app/test/cache_coordinator_test.dart b/apps/mobile/packages/forum_app/test/cache_coordinator_test.dart
new file mode 100644
index 00000000..8e44d1c9
--- /dev/null
+++ b/apps/mobile/packages/forum_app/test/cache_coordinator_test.dart
@@ -0,0 +1,307 @@
+import 'dart:async';
+
+import 'package:drift/native.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:forum_app/src/offline/drift_cache.dart';
+import 'package:forum_app/src/storage/cache_coordinator.dart';
+
+class _JournalDatabase extends AppDatabase {
+  _JournalDatabase() : super(NativeDatabase.memory());
+  bool failWrite = false;
+  bool failFinish = false;
+  @override
+  Future<void> setOperation(String name, String value) {
+    if (failWrite) return Future.error(StateError('Journal write failure'));
+    return super.setOperation(name, value);
+  }
+
+  @override
+  Future<void> finishOperation(String name) {
+    if (failFinish) return Future.error(StateError('Journal finish failure'));
+    return super.finishOperation(name);
+  }
+}
+
+void main() {
+  test(
+    'partial cleanup retains a retry journal and only failed owners stay suspended',
+    () async {
+      final db = AppDatabase(NativeDatabase.memory());
+      addTearDown(db.close);
+      var fails = true;
+      var invalidations = 0, clears = 0;
+      var holds = 0, resumes = 0, depth = 0;
+      final coordinator = CacheCoordinator(
+        database: db,
+        databaseBytes: () async => 100,
+        onInvalidated: (_) => invalidations++,
+        owners: {
+          CacheCategory.media: CacheOwner(
+            invalidate: () {
+              holds++;
+              depth++;
+            },
+            resume: () {
+              resumes++;
+              depth--;
+            },
+            bytes: () async => 20,
+            clear: () async {
+              clears++;
+              if (fails) throw StateError('Disk failure');
+            },
+          ),
+        },
+      );
+      final first = await coordinator.clear({
+        CacheCategory.forum,
+        CacheCategory.media,
+      });
+      expect(first.failed, {CacheCategory.media});
+      expect(await coordinator.pending(), {CacheCategory.media});
+      expect(db.available(CacheCategory.forum), isTrue);
+      expect(db.available(CacheCategory.media), isFalse);
+      expect(depth, 1);
+      expect(resumes, 0);
+      expect((await coordinator.resume()).failed, {CacheCategory.media});
+      expect(depth, 1);
+      expect(holds, 1);
+      fails = false;
+      expect((await coordinator.resume()).succeeded, isTrue);
+      expect(await coordinator.pending(), isEmpty);
+      expect(db.available(CacheCategory.media), isTrue);
+      expect(invalidations, 3);
+      expect(clears, 3);
+      expect(holds, 1);
+      expect(resumes, 1);
+      expect(depth, 0);
+    },
+  );
+
+  test(
+    'selected cleanup cannot delete other categories or user-work records',
+    () async {
+      final db = AppDatabase(NativeDatabase.memory());
+      addTearDown(db.close);
+      await db.customStatement(
+        "INSERT INTO cache_entries VALUES ('s','forum','a','{}',0,0,2,1)",
+      );
+      await db.customStatement(
+        "INSERT INTO cache_entries VALUES ('s','chat','b','{}',0,0,2,1)",
+      );
+      await db.customStatement(
+        "INSERT INTO campus_snapshots VALUES ('s',7,'binding',1,'{}','now')",
+      );
+      final coordinator = CacheCoordinator(
+        database: db,
+        databaseBytes: () async => 0,
+        onInvalidated: (_) {},
+        owners: {},
+      );
+      await coordinator.clear({CacheCategory.forum});
+      final rows = await db
+          .customSelect('SELECT domain FROM cache_entries')
+          .get();
+      expect(rows.map((r) => r.read<String>('domain')), ['chat']);
+      expect(
+        await db.customSelect('SELECT * FROM campus_snapshots').get(),
+        hasLength(1),
+      );
+    },
+  );
+  test(
+    'a failed initial journal write stays fenced and resume retries each hold once',
+    () async {
+      final db = _JournalDatabase();
+      addTearDown(db.close);
+      var holds = 0, releases = 0, clears = 0;
+      final coordinator = CacheCoordinator(
+        database: db,
+        databaseBytes: () async => 0,
+        onInvalidated: (_) {},
+        owners: {
+          CacheCategory.media: CacheOwner(
+            invalidate: () => holds++,
+            resume: () => releases++,
+            bytes: () async => 0,
+            clear: () async {
+              clears++;
+            },
+          ),
+        },
+      );
+      db.failWrite = true;
+      await expectLater(
+        coordinator.clear({CacheCategory.forum, CacheCategory.media}),
+        throwsStateError,
+      );
+      expect(holds, 1);
+      expect(releases, 0);
+      expect(clears, 0);
+      expect(db.available(CacheCategory.forum), isFalse);
+      expect(db.available(CacheCategory.media), isFalse);
+      expect(await coordinator.pending(), isEmpty);
+      db.failWrite = false;
+      expect((await coordinator.resume()).succeeded, isTrue);
+      expect(holds, 1);
+      expect(releases, 1);
+      expect(clears, 1);
+      expect(db.available(CacheCategory.forum), isTrue);
+      expect(db.available(CacheCategory.media), isTrue);
+    },
+  );
+
+  test(
+    'pending categories recovered from the journal fence their owners before deletion',
+    () async {
+      final db = AppDatabase(NativeDatabase.memory());
+      addTearDown(db.close);
+      await db.setOperation('clear', '["media"]');
+      var depth = 0, clears = 0;
+      final notifications = <Set<CacheCategory>>[];
+      final coordinator = CacheCoordinator(
+        database: db,
+        databaseBytes: () async => 0,
+        onInvalidated: notifications.add,
+        owners: {
+          CacheCategory.media: CacheOwner(
+            invalidate: () => depth++,
+            resume: () => depth--,
+            bytes: () async => 0,
+            clear: () async {
+              expect(depth, 1);
+              expect(db.available(CacheCategory.media), isFalse);
+              clears++;
+            },
+          ),
+        },
+      );
+      expect(
+        (await coordinator.clear({CacheCategory.forum})).succeeded,
+        isTrue,
+      );
+      expect(clears, 1);
+      expect(depth, 0);
+      expect(
+        notifications.expand((c) => c),
+        containsAll(
+          CacheCategory.values.where(
+            (c) => c == CacheCategory.forum || c == CacheCategory.media,
+          ),
+        ),
+      );
+      expect(await coordinator.pending(), isEmpty);
+    },
+  );
+
+  test(
+    'a failed final journal commit does not resume an owner before durable success',
+    () async {
+      final db = _JournalDatabase();
+      addTearDown(db.close);
+      var holds = 0, releases = 0;
+      final coordinator = CacheCoordinator(
+        database: db,
+        databaseBytes: () async => 0,
+        onInvalidated: (_) {},
+        owners: {
+          CacheCategory.media: CacheOwner(
+            invalidate: () => holds++,
+            resume: () => releases++,
+            bytes: () async => 0,
+            clear: () async {},
+          ),
+        },
+      );
+      db.failFinish = true;
+      await expectLater(
+        coordinator.clear({CacheCategory.media}),
+        throwsStateError,
+      );
+      expect(await coordinator.pending(), {CacheCategory.media});
+      expect(holds, 1);
+      expect(releases, 0);
+      db.failFinish = false;
+      expect((await coordinator.resume()).succeeded, isTrue);
+      expect(holds, 1);
+      expect(releases, 1);
+    },
+  );
+
+  test('identical concurrent cleanup shares the in-flight operation', () async {
+    final db = AppDatabase(NativeDatabase.memory());
+    addTearDown(db.close);
+    final entered = Completer<void>();
+    final release = Completer<void>();
+    var clears = 0;
+    final coordinator = CacheCoordinator(
+      database: db,
+      databaseBytes: () async => 0,
+      onInvalidated: (_) {},
+      owners: {
+        CacheCategory.media: CacheOwner(
+          invalidate: () {},
+          clear: () async {
+            clears++;
+            entered.complete();
+            await release.future;
+          },
+          bytes: () async => 0,
+        ),
+      },
+    );
+
+    final first = coordinator.clear({CacheCategory.forum, CacheCategory.media});
+    await entered.future;
+    final second = coordinator.clear({
+      CacheCategory.forum,
+      CacheCategory.media,
+    });
+
+    expect(identical(second, first), isTrue);
+    release.complete();
+    final results = await Future.wait([first, second]);
+    expect(results.every((result) => result.succeeded), isTrue);
+    expect(clears, 1);
+  });
+
+  test(
+    'concurrent cleanup for another category waits and runs afterward',
+    () async {
+      final db = AppDatabase(NativeDatabase.memory());
+      addTearDown(db.close);
+      await db.customStatement(
+        "INSERT INTO cache_entries VALUES ('s','forum','a','{}',0,0,2,1)",
+      );
+      final entered = Completer<void>();
+      final release = Completer<void>();
+      final coordinator = CacheCoordinator(
+        database: db,
+        databaseBytes: () async => 0,
+        onInvalidated: (_) {},
+        owners: {
+          CacheCategory.media: CacheOwner(
+            invalidate: () {},
+            clear: () async {
+              entered.complete();
+              await release.future;
+            },
+            bytes: () async => 0,
+          ),
+        },
+      );
+
+      final first = coordinator.clear({CacheCategory.media});
+      await entered.future;
+      final second = coordinator.clear({CacheCategory.forum});
+      release.complete();
+
+      final results = await Future.wait([first, second]);
+      expect(results.every((result) => result.succeeded), isTrue);
+      expect(
+        await db.customSelect('SELECT * FROM cache_entries').get(),
+        isEmpty,
+      );
+    },
+  );
+}

