+import 'dart:async';
+import 'dart:convert';
+import 'dart:io';
+import 'dart:typed_data';
+import 'package:dio/dio.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:forum_app/src/storage/media_repository.dart';
+
+class _Http implements HttpClientAdapter {
+  final requests = <RequestOptions>[];
+  Future<ResponseBody> Function(RequestOptions)? handle;
+  @override
+  Future<ResponseBody> fetch(
+    RequestOptions options,
+    Stream<Uint8List>? stream,
+    Future<void>? cancel,
+  ) async {
+    requests.add(options);
+    return handle?.call(options) ?? response();
+  }
+
+  @override
+  void close({bool force = false}) {}
+}
+
+class _CountingDirectory implements Directory {
+  _CountingDirectory(this.directory);
+  final Directory directory;
+  int listings = 0;
+  @override
+  String get path => directory.path;
+  @override
+  Future<Directory> create({bool recursive = false}) =>
+      directory.create(recursive: recursive);
+  @override
+  Stream<FileSystemEntity> list({
+    bool recursive = false,
+    bool followLinks = true,
+  }) {
+    listings++;
+    return directory.list(recursive: recursive, followLinks: followLinks);
+  }
+
+  @override
+  dynamic noSuchMethod(Invocation invocation) => super.noSuchMethod(invocation);
+}
+
+ResponseBody response({
+  String cache = 'public, max-age=60',
+  List<int> bytes = const [1, 2, 3],
+  int status = 200,
+  Map<String, List<String>> extra = const {},
+}) => ResponseBody.fromBytes(
+  bytes,
+  status,
+  headers: {
+    'content-type': ['image/gif'],
+    'cache-control': [cache],
+    ...extra,
+  },
+);
+const _origin = 'https://example.test';
+const _url = '$_origin/image.gif';
+void main() {
+  late Directory dir;
+  late _Http http;
+  late Dio dio;
+  late DateTime now;
+  late MediaRepository cache;
+  setUp(() async {
+    dir = await Directory.systemTemp.createTemp('yourtj-media-test-');
+    http = _Http();
+    dio = Dio()..httpClientAdapter = http;
+    now = DateTime.utc(2026, 9, 29);
+    cache = MediaRepository(
+      directory: () async => dir,
+      dio: dio,
+      now: () => now,
+    );
+  });
+  tearDown(() async {
+    cache.dispose();
+    await dir.delete(recursive: true);
+  });
+  Future<Uint8List> load({String url = _url, String scope = 'site:42:zh'}) =>
+      cache.load(url, scopeKey: scope, apiOrigin: _origin);
+  group('pending upload previews (issue #975)', () {
+    const upload = '$_origin/file/img/2026/10/02/pending.png';
+    var tokenReads = 0;
+    Future<String?> readToken() async {
+      tokenReads++;
+      return 'session-token';
+    }
+
+    setUp(() => tokenReads = 0);
+    Future<Uint8List> loadWithSession(
+      String url, {
+      String scope = 'site:42:zh',
+    }) => cache.load(
+      url,
+      scopeKey: scope,
+      apiOrigin: _origin,
+      readAccessToken: readToken,
+    );
+
+    test('a site upload that 404s anonymously retries once with the session '
+        'and is never stored', () async {
+      http.handle = (request) async =>
+          request.headers['Authorization'] == 'Bearer session-token'
+          ? response(cache: 'private, no-store', bytes: [7, 7])
+          : response(status: 404);
+      expect(await loadWithSession(upload), [7, 7]);
+      expect(http.requests.map((r) => r.headers['Authorization']), [
+        null,
+        'Bearer session-token',
+      ]);
+      expect(await cache.usageBytes(), 0);
+    });
+
+    test('even a public answer to the session request is not stored', () async {
+      http.handle = (request) async =>
+          request.headers.containsKey('Authorization')
+          ? response()
+          : response(status: 404);
+      await loadWithSession(upload);
+      expect(await cache.usageBytes(), 0);
+    });
+
+    test('public images, other hosts, redirects and unresolved scopes never '
+        'carry the session', () async {
+      http.handle = (_) async => response();
+      await loadWithSession(upload);
+      http.handle = (_) async => response(status: 404);
+      await expectLater(
+        loadWithSession('https://cdn.example.test/file/img/x.png'),
+        throwsA(anything),
+      );
+      await expectLater(
+        loadWithSession('$_origin/image.gif'),
+        throwsA(anything),
+      );
+      await expectLater(
+        loadWithSession(upload, scope: 'pending:0'),
+        throwsA(anything),
+      );
+      http.handle = (request) async => request.uri.toString() == '$upload?r=1'
+          ? response(
+              status: 302,
+              extra: {
+                'location': [upload],
+              },
+            )
+          : response(status: 404);
+      await expectLater(loadWithSession('$upload?r=1'), throwsA(anything));
+      expect(tokenReads, 0);
+      expect(
+        http.requests.every((r) => !r.headers.containsKey('Authorization')),
+        isTrue,
+      );
+    });
+
+    test('a scope change while reading the token drops the request', () async {
+      http.handle = (_) async => response(status: 404);
+      final pending = cache.load(
+        upload,
+        scopeKey: 'site:42:zh',
+        apiOrigin: _origin,
+        readAccessToken: () async {
+          cache.invalidate();
+          return 'session-token';
+        },
+      );
+      await expectLater(pending, throwsStateError);
+      expect(http.requests, hasLength(1));
+    });
+  });
+
+  test(
+    'chat origin policy rejects tracking redirects before requesting them',
+    () async {
+      http.handle = (_) async => response(
+        status: 302,
+        extra: {
+          'location': ['https://tracker.example/pixel.gif'],
+        },
+      );
+      await expectLater(
+        cache.load(
+          _url,
+          scopeKey: 'site:42:zh',
+          apiOrigin: _origin,
+          allowedOrigins: {_origin},
+        ),
+        throwsFormatException,
+      );
+      expect(http.requests.map((r) => r.uri.toString()), [_url]);
+    },
+  );
+
+  test('chat origin policy permits explicitly trusted CDN redirects', () async {
+    const cdn = 'https://cdn.example.test';
+    http.handle = (request) async => request.uri.toString() == _url
+        ? response(
+            status: 302,
+            extra: {
+              'location': ['$cdn/image.gif'],
+            },
+          )
+        : response();
+    expect(
+      await cache.load(
+        _url,
+        scopeKey: 'site:42:zh',
+        apiOrigin: _origin,
+        allowedOrigins: {_origin, cdn},
+      ),
+      [1, 2, 3],
+    );
+    expect(http.requests.map((r) => r.uri.toString()), [
+      _url,
+      '$cdn/image.gif',
+    ]);
+  });
+  test(
+    'public fresh image survives repository restart and scopes stay separate',
+    () async {
+      expect(await load(), [1, 2, 3]);
+      expect(await load(), [1, 2, 3]);
+      expect(http.requests.length, 1);
+      cache.dispose();
+      cache = MediaRepository(
+        directory: () async => dir,
+        dio: dio,
+        now: () => now,
+      );
+      expect(await load(), [1, 2, 3]);
+      expect(http.requests.length, 1);
+      await load(scope: 'site:99:zh');
+      await load(scope: 'site:42:de');
+      expect(http.requests.length, 3);
+    },
+  );
+  for (final policy in [
+    'private, max-age=60',
+    'no-store',
+    'public, no-cache',
+    'public, max-age=0',
+    'max-age=60',
+    'public, max-age=60, must-revalidate',
+  ]) {
+    test('HTTP policy $policy is respected', () async {
+      http.handle = (_) async => response(cache: policy);
+      await load();
+      if (policy.endsWith('must-revalidate')) {
+        now = now.add(const Duration(minutes: 2));
+        http.handle = (_) async => throw StateError('offline');
