+  test('only AI moderation block codes trigger the blocked dialog', () {
+    for (final code in <String>[
+      'content.aiModeration.blocked',
+      'content.aiModeration.externalImageBlocked',
+    ]) {
+      expect(
+        isModerationBlocked(
