+import 'package:forum_app/src/updates/ios_store_release.dart';
+import 'package:shared_preferences/shared_preferences.dart';
+
+Map<String, dynamic> note(
+  String id,
+  String title, {
+  List<String> platforms = const ['android'],
+  bool required = false,
+  String kind = 'feature',
+}) => {
+  'id': id,
+  'title': title,
+  'summary': '$title summary',
+  'platforms': platforms,
+  'kind': kind,
+  if (required) 'required': true,
+};
+
+Map<String, dynamic> release(
+  int build, {
+  List<String> channels = const ['android'],
+  List<dynamic> highlights = const [],
+  List<dynamic> breaking = const [],
+  List<dynamic> actions = const [],
+}) => {
+  'version': '1.0.${build - 1}',
+  'buildNumber': build,
+  'channels': channels,
+  'highlights': highlights,
+  'breaking': breaking,
+  'requiredActions': actions,
+  'testflightNotes': const [],
+};
+
+Map<String, dynamic> catalog() => {
+  'schemaVersion': 1,
+  'historyCoverage': {
+    'source': 'github-release-receipts',
+    'publishedAt': '2026-10-03T00:00:00Z',
+    'byChannel': {
+      'android': {
+        'completeFromBuild': 4,
+        'throughBuild': 7,
+        'coveredBuilds': [4, 5, 6, 7],
+      },
+      'ios-app-store': {
+        'completeFromBuild': 5,
+        'throughBuild': 6,
+        'coveredBuilds': [6],
+      },
+      'ios-testflight': {
+        'completeFromBuild': 6,
+        'throughBuild': 7,
+        'coveredBuilds': [7],
+      },
+    },
+  },
+  'releases': [
+    release(4),
+    release(
+      5,
+      breaking: [note('shared-update', 'Older title', required: true)],
+    ),
