+
+class _StatusHarnessState extends State<_StatusHarness> {
+  bool working = false;
+  bool failed = false;
+  bool needsPermission = false;
+  bool ready = false;
+  int receivedBytes = 0;
+
+  void setStatus({
+    bool working = false,
+    bool failed = false,
+    bool needsPermission = false,
+    bool ready = false,
+    int? receivedBytes,
+  }) => setState(() {
+    this.working = working;
+    this.failed = failed;
+    this.needsPermission = needsPermission;
+    this.ready = ready;
+    this.receivedBytes = receivedBytes ?? this.receivedBytes;
+  });
+
+  @override
+  Widget build(BuildContext context) => Center(
+    child: SizedBox(
+      width: 280,
+      child: UpdatePromptSheet(
+        version: '1.2.0',
+        notes: const [],
+        historyComplete: true,
+        working: working,
+        failed: failed,
+        needsPermission: needsPermission,
+        ready: ready,
+        receivedBytes: receivedBytes,
+        primaryLabel: 'Download',
+        onPrimary: () {},
+        onLater: () {},
+      ),
+    ),
+  );
+}
+
+class _DialogHarness extends StatefulWidget {
+  const _DialogHarness({super.key, required this.notes});
+  final List<ReleaseNote> notes;
+
+  @override
+  State<_DialogHarness> createState() => _DialogHarnessState();
+}
+
+class _DialogHarnessState extends State<_DialogHarness> {
+  bool working = false;
+  bool failed = false;
+  bool needsPermission = false;
+  bool ready = false;
+  int receivedBytes = 0;
+  int downloadTapped = 0;
+  int permissionTapped = 0;
+  int cancelTapped = 0;
+
+  void setStatus({
+    bool working = false,
+    bool failed = false,
+    bool needsPermission = false,
+    bool ready = false,
+    int? receivedBytes,
+  }) => setState(() {
+    this.working = working;
+    this.failed = failed;
+    this.needsPermission = needsPermission;
+    this.ready = ready;
+    this.receivedBytes = receivedBytes ?? this.receivedBytes;
+  });
+
+  @override
+  Widget build(BuildContext context) {
+    final l10n = AppLocalizations.of(context);
+    return Scaffold(
+      body: Align(
+        alignment: Alignment.bottomCenter,
+        child: UpdatePromptSheet(
+          version: '1.2.0',
+          installedVersion: '1.1.0',
+          sizeBytes: 5000000,
+          notes: widget.notes,
+          historyComplete: false,
+          working: working,
+          failed: failed,
+          needsPermission: needsPermission,
+          ready: ready,
+          receivedBytes: receivedBytes,
+          primaryLabel: needsPermission
+              ? l10n.updateOpenPermissionSettings
+              : ready
+              ? l10n.updateInstall
+              : failed
+              ? l10n.updateRetry
+              : l10n.updateDownload,
+          onPrimary: () {
+            if (needsPermission) {
+              permissionTapped++;
+            } else {
+              downloadTapped++;
+            }
+          },
+          onCancel: () => cancelTapped++,
+          onLater: () {},
+          onSkip: () {},
+        ),
+      ),
+    );
+  }
+}

