+    expect(prefs.containsKey('pk.plans'), false);
+  });
+  test('a failed transaction does not advance any part of a snapshot', () async {
+    final db = UserWorkDatabase.instance;
+    await db.writeBatch(scope, 'schedule', {'a': 'old', 'b': 'old'});
